struct Resource {};

// Deleter: Stores no state -> EBO enabled
struct CustomDeleter {
    void operator()(Resource* r) const { delete r; }
};

// Unique pointer definition
using PtrType = std::unique_ptr<Resource, CustomDeleter>;

// Key implementation detail: size optimization (Empty Base Optimization)
static_assert(sizeof(PtrType) == sizeof(Resource*));

// Deleter stores state (e.g., function pointer) -> increased size
using FuncPtr = void(*)(Resource*);
using FatPtr = std::unique_ptr<Resource, FuncPtr>;

static_assert(sizeof(FatPtr) > sizeof(Resource*));

PtrType p(new Resource{});
